        Equal(Route(resultA), Route(transplanted), "Fork preserves source route");
        if (Route(transplanted) == Route(resultB)
            || CardContinuationContractHistoryText(transplanted) == CardContinuationContractHistoryText(resultB))
            throw new InvalidOperationException("Copied result unexpectedly preserved the consuming branch prefix.");
        for (int i = 0; i < a.History.Count(); i++)
            if (!ReferenceEquals(a.History[i], transplanted.History[i]))
                throw new InvalidOperationException("Source history prefix identity unexpectedly changed during Fork.");

