        CombatPredictionSimulator[] children = Enumerable.Range(0, 16).Select(_ => resultA.Fork()).ToArray();
        await Task.WhenAll(children.Select((child, i) => Task.Run(() => {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
