                player.Creature, i + 1, player.Creature);
            if (State(child) == State(resultA))
                throw new InvalidOperationException("Child strength mutation was not branch-owned.");
            Equal(resultBefore, Full(resultA), "template after child mutation " + i);
            Equal(Route(resultA), Route(child), "child history identity " + i);
        })));
        Equal(aBefore, Full(a), "source parent after all child mutations");
        Equal(bBefore, Full(b), "consuming parent after all child mutations");
        Equal(basisBefore, Full(basis), "frozen root parent");
        Equal(liveBefore, ContinuationStamp.CaptureLive(live).StateText, "live isolation before native play");

        CombatPredictionSimulator expected = Replay(basis, "INFLAME", "BARRICADE", "BACKFLIP");
        using CancellationTokenSource deadline = new(TimeSpan.FromSeconds(12));
        foreach (string id in new[] { "INFLAME", "BARRICADE", "BACKFLIP" })
        {
            var liveCard = player.PlayerCombatState!.Hand.Cards.Single(c => c.Id.Entry == id);
            GameAction action = await SolverController.EnqueueAndCaptureActionAsync(
                queued => queued is PlayCardAction played
                    && ReferenceEquals(played.NetCombatCard.ToCardModelOrNull(), liveCard),
                () => { if (!liveCard.TryManualPlay(null)) throw new InvalidOperationException("Native card not playable: " + id); },
                deadline.Token);
            await action.CompletionTask.WaitAsync(deadline.Token);
        }
        Equal(State(expected), ContinuationStamp.CaptureLive(live).StateText, "native full ordered state and RNG");
        AssertSnapshotEqual(CaptureSimulated(expected, (SimulatedCombatState)expected.State.CombatState,
            player, target), CaptureActual(live, player, target), "TRANSITION_PREFIX", "INFLAME_BARRICADE_BACKFLIP");
        _completedChecks.Add("TransitionPrefix:NaturalSameStateKeyAndHistoryCount:DifferentPrefixes:CopiedResultWrongPrefix:NativeFullState:SixteenForks:ParentLiveRngIsolation");
        _completedChecks.Add("TransitionPrefix:SourceRoute=" + Route(resultA) + ";ConsumerRoute=" + Route(resultB)
            + ";State=" + Hash(State(resultA)) + ";SourceHistory=" + Hash(CardContinuationContractHistoryText(resultA))
            + ";ConsumerHistory=" + Hash(CardContinuationContractHistoryText(resultB)));
    }
}

